// GENERATED by agent-radar-art/export_crew.py: the animation-studio crew as 20 by 28 grids. Do not edit by hand.
// One character per palette key (see peopleColors in office.ts); `.` is empty. Heads (rows 0-17) change with the
// mood, bodies (rows 18-23) with the standing/seated view, legs (rows 24-27) with the walking pose.

export type Mood = 'normal' | 'work' | 'wow' | 'sleepy' | 'happy' | 'stuck'
export type Pose = 'stand' | 'step-a' | 'step-b'
export type CrewRole = 'lead' | 'explore' | 'scout' | 'plan' | 'architect' | 'reviewer' | 'builder' | 'researcher' | 'general' | 'other'
export type CrewSprite = {
  /** Rows 0-17 by mood. */
  head: Readonly<Record<Mood, readonly string[]>>
  /** Rows 18-19: what shows above a desk. */
  seatBody: readonly string[]
  /** Rows 18-23 with the held item, for a standing or walking person. */
  body: readonly string[]
  /** Rows 24-27 by pose. */
  legs: Readonly<Record<Pose, readonly string[]>>
}
export type CrewLook = { hair: string; eyes: string; skin: string; outfit: string; accent: string; kit: string; pants: string }

